package com.tekwatt.reporting.service;import static org.assertj.core.api.Assertions.assertThat;import com.fasterxml.jackson.databind.ObjectMapper;import com.tekwatt.reporting.entity.ReportType;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;class HtmlReportGeneratorTests{@Test void createsSafePrintableHtml()throws Exception{var data=new ObjectMapper().readTree("[{\"date\":\"2026-08-01\",\"label\":\"A&B <fast>\"}]");String result=new String(new HtmlReportGenerator().generate(ReportType.DAILY,data),StandardCharsets.UTF_8);assertThat(result).contains("<!doctype html>","A&amp;B &lt;fast&gt;","@media print").doesNotContain("A&B <fast>");}}
